using System.Text.Json.Serialization; using UniversalSimulation.Application; using UniversalSimulation.Domain; using UniversalSimulation.Engine; using UniversalSimulation.Infrastructure; using UniversalSimulation.Worker;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddSingleton<SimulationEngine>(); builder.Services.AddSingleton<ISimulationStore,PostgresSimulationStore>(); builder.Services.AddSingleton<SimulationCoordinator>(); builder.Services.AddHostedService<ContinuousSimulationWorker>(); builder.Services.ConfigureHttpJsonOptions(o=>o.SerializerOptions.Converters.Add(new JsonStringEnumConverter())); var app=builder.Build(); app.UseDefaultFiles(); app.UseStaticFiles();
app.MapGet("/api/health",()=>Results.Ok(new{status="ok",time=DateTimeOffset.UtcNow})); app.MapGet("/api/universes",(SimulationCoordinator c)=>c.Universes); app.MapGet("/api/universes/{id:guid}",(Guid id,SimulationCoordinator c)=>c.Find(id) is{}u?Results.Ok(u):Results.NotFound()); app.MapPost("/api/universes",async(CreateUniverseRequest r,SimulationCoordinator c,CancellationToken ct)=>Results.Created("/api/universes",await c.Create(r.Name,r.Parameters??new(),ct))); app.MapPost("/api/scenarios/cosmic-refinement",async(CosmicRefinementScenarioRequest? r,SimulationCoordinator c,CancellationToken ct)=>Results.Created("/api/universes",await c.CreateCosmicRefinementScenario(r?.Scale,r?.LivingWorldTarget??false,ct))); app.MapPatch("/api/universes/{id:guid}/control",async(Guid id,ControlRequest r,SimulationCoordinator c,CancellationToken ct)=>await c.Control(id,r.Status,r.Speed,ct)?Results.NoContent():Results.NotFound()); app.MapPost("/api/universes/{id:guid}/step",async(Guid id,StepRequest r,SimulationCoordinator c,CancellationToken ct)=>await c.Step(id,r.Ticks,ct)?Results.NoContent():Results.NotFound()); app.MapDelete("/api/universes/{id:guid}",async(Guid id,SimulationCoordinator c,CancellationToken ct)=>await c.Delete(id,ct)?Results.NoContent():Results.NotFound()); app.MapGet("/api/universes/{id:guid}/events",async(Guid id,int? limit,EventImportance? importance,ISimulationStore s,CancellationToken ct)=>Results.Ok(await s.Events(id,limit??100,importance,ct))); app.MapFallbackToFile("index.html"); app.Run();
record CreateUniverseRequest(string Name,UniverseParameters? Parameters); record CosmicRefinementScenarioRequest(string? Scale="World",bool LivingWorldTarget=false); record ControlRequest(SimulationStatus? Status,double? Speed); record StepRequest(int Ticks=1); public partial class Program{}
